def doble(x):
    return x * 2

def cuadruple(x):
    return doble(doble(x))

resultado = cuadruple(3)
print(resultado)

class Cuenta:
    def __init__(self, saldo):
        self.saldo = saldo

    def depositar(self, monto):
        self.saldo = self.saldo + monto

cuenta = Cuenta(100)
cuenta.depositar(50)
print(cuenta.saldo)

def retirar(saldo, monto):
    if monto > saldo:
        raise ValueError("Saldo insuficiente")
    return saldo - monto

try:
    nuevo = retirar(100, 150)
    print("Retiro hecho")
except ValueError as error:
    print("No se pudo:", error)
print("Fin")

from dataclasses import dataclass

@dataclass(frozen=True)
class Monto:
    valor: int
    moneda: str

    def __add__(self, otro):
        if self.moneda != otro.moneda:
            raise ValueError("Monedas distintas")
        return Monto(self.valor + otro.valor, self.moneda)

a = Monto(10, "PEN")
b = Monto(5, "PEN")
total = a + b
print(total)
print(a == Monto(10, "PEN"))

def descuento(total, frecuente):
    if frecuente:
        return total * 10 // 100
    return 0

def test_frecuente_tiene_10_por_ciento():
    assert descuento(200, True) == 20

def test_no_frecuente_no_tiene_descuento():
    assert descuento(200, False) == 0

test_frecuente_tiene_10_por_ciento()
test_no_frecuente_no_tiene_descuento()
