class LimiteExcedido(Exception):
    pass

class Pedido:
    def __init__(self, limite):
        self._lineas = []
        self._limite = limite

    def agregar(self, producto, precio):
        if self.total() + precio > self._limite:
            raise LimiteExcedido(producto)
        self._lineas.append((producto, precio))

    def total(self):
        suma = 0
        for _, precio in self._lineas:
            suma = suma + precio
        return suma

pedido = Pedido(limite=10)
pedido.agregar("pan", 4)
pedido.agregar("leche", 5)
try:
    pedido.agregar("cafe", 9)
except LimiteExcedido as error:
    print("Rechazado:", error)
print(pedido.total())
